Problem:
A strawberry farmer delivers his strawberries in two types of containers, a box and a bucket. A box contains 7 units of strawberries whereas a bucket contains 9 units of strawberries. The farmer has access to 500 boxes and 300 buckets. Buckets sell for more profit; therefore, the farmer wants to sell at least three times more buckets than boxes. Additionally, he can transport at most 650 containers and at least 25 must be boxes. How many of each type of container should the farmer order to maximize the total amount of strawberries he can transport?

Model and facts:
{
 "model": {
  "variables": [
   {
    "name": "boxes",
    "lower": 0.0,
    "upper": 500.0,
    "integer": true
   },
   {
    "name": "buckets",
    "lower": 0.0,
    "upper": 300.0,
    "integer": true
   }
  ],
  "objective": {
   "sense": "max",
   "terms": [
    {
     "var": "boxes",
     "coef": 7.0
    },
    {
     "var": "buckets",
     "coef": 9.0
    }
   ]
  },
  "constraints": [
   {
    "name": "buckets_at_least_three_times_boxes",
    "terms": [
     {
      "var": "buckets",
      "coef": 1.0
     },
     {
      "var": "boxes",
      "coef": -3.0
     }
    ],
    "sense": ">=",
    "rhs": 0.0
   },
   {
    "name": "max_total_containers",
    "terms": [
     {
      "var": "boxes",
      "coef": 1.0
     },
     {
      "var": "buckets",
      "coef": 1.0
     }
    ],
    "sense": "<=",
    "rhs": 650.0
   },
   {
    "name": "min_boxes",
    "terms": [
     {
      "var": "boxes",
      "coef": 1.0
     }
    ],
    "sense": ">=",
    "rhs": 25.0
   }
  ]
 },
 "facts": {
  "objective": 3400.0,
  "values": {
   "boxes": 100.0,
   "buckets": 300.0
  },
  "binding": [
   "buckets_at_least_three_times_boxes"
  ],
  "slack": {
   "buckets_at_least_three_times_boxes": 0.0,
   "max_total_containers": 250.0,
   "min_boxes": 75.0
  },
  "shadow_prices": null,
  "limits": {
   "buckets_at_least_three_times_boxes": {
    "dropped_improves": true,
    "loosened_improves": false
   },
   "max_total_containers": {
    "dropped_improves": false,
    "loosened_improves": false
   },
   "min_boxes": {
    "dropped_improves": false,
    "loosened_improves": false
   }
  }
 }
}
